import asyncio
from sqlalchemy import select
from database import AsyncSessionLocal
from models.jobhunt_routing import JobhuntRouting, PROFILE_WILDCARD
from services.routing import (
    CAPABILITY_CATALOG,
    CAPABILITY_MATCHING,
    MODE_CORE_PRIMARY,
    MODE_CORE_READ,
    read_all_modes_fresh,
    set_routing,
)

ACTOR = "optimization-2026-10-12"
CAPABILITIES = (CAPABILITY_CATALOG, CAPABILITY_MATCHING)

async def main():
    async with AsyncSessionLocal() as db:
        before = await read_all_modes_fresh(db, list(CAPABILITIES))
    for capability in CAPABILITIES:
        modes = before[capability]
        if modes == [MODE_CORE_PRIMARY]:
            continue
        if modes != [MODE_CORE_READ]:
            raise SystemExit(
                f"ABORTA: {capability} tiene modos efectivos inesperados: {modes}"
            )
        async with AsyncSessionLocal() as db:
            await set_routing(
                db, capability, MODE_CORE_PRIMARY, updated_by=ACTOR
            )
    async with AsyncSessionLocal() as db:
        after = await read_all_modes_fresh(db, list(CAPABILITIES))
        rows = (await db.execute(select(JobhuntRouting).where(
            JobhuntRouting.profile_id == PROFILE_WILDCARD,
            JobhuntRouting.capability.in_(CAPABILITIES),
        ))).scalars().all()
    expected = {capability: [MODE_CORE_PRIMARY] for capability in CAPABILITIES}
    if after != expected:
        raise SystemExit(f"ABORTA: routing final inesperado: {after}")
    by_capability = {row.capability: row for row in rows}
    if set(by_capability) != set(CAPABILITIES) or any(
        row.mode != MODE_CORE_PRIMARY or row.updated_by != ACTOR
        for row in by_capability.values()
    ):
        raise SystemExit("ABORTA: filas wildcard o auditoría final inesperadas")
    print("routing final verificado:", after)

asyncio.run(main())
